SELECT CASE WHEN s.sqft >= 13180 THEN 'high' WHEN s.sqft >= 3486 THEN 'mid' ELSE 'low' END sqft_bucket, ROUND(STDDEV(i.quantity), 2) stddev_quantity FROM inventory i JOIN products p ON i.product_id = p.id LEFT JOIN stores s ON i.store_id = s.id GROUP BY CASE WHEN s.sqft >= 13180 THEN 'high' WHEN s.sqft >= 3486 THEN 'mid' ELSE 'low' END ORDER BY stddev_quantity DESC, sqft_bucket ASC
